import { useCallback, useEffect, useId, useRef, useState } from 'react';
import type { DragEvent, FormEvent } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, BarChart3, BookOpen, Check, CheckCheck, ChevronDown, ChevronRight, CircleAlert, Clock3, Coins, Database, FileArchive, FileCheck2, FileCode2, FileSpreadsheet, Files, Fingerprint, FlaskConical, FolderOpen, History, LayoutDashboard, Lightbulb, LoaderCircle, LockKeyhole, LogOut, Menu, Play, Plus, RefreshCw, Search, ShieldCheck, SlidersHorizontal, Sparkles, Table2, Trash2, UploadCloud, Workflow, X } from 'lucide-react';
import { api, ApiError } from './api';
import AuthScreen from './AuthScreen';
import type { Job, Result, Session, Upload, UploadSchema, Usage } from './types';
import Brief from './Brief';
import PublicExamples from './PublicExamples';
import ChartCard from './ChartCard';
import Exploration, { EdaOverviewSummary } from './Exploration';
import UpgradeAnalysisDialog from './UpgradeAnalysisDialog';
import { useDialogFocus } from './useDialogFocus';
import UsagePage, { AuthorizeModal, ModelChoice, usageSummary } from './Usage';
import type { UsageState } from './Usage';

type Icon = typeof Database;
type Page = 'workspace' | 'history' | 'guide' | 'usage';
type Tab = 'overview' | 'charts' | 'data' | 'agent';
const scrollTop = () => window.scrollTo({ top: 0, behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
const number = (value: number) => new Intl.NumberFormat('zh-CN', value !== 0 && Math.abs(value) < .01 ? { notation: 'scientific', maximumFractionDigits: 3 } : { maximumFractionDigits: 2 }).format(value);
const date = (value: string) => new Intl.DateTimeFormat('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Shanghai' }).format(new Date(value.endsWith('Z') || /[+-]\d\d:\d\d$/.test(value) ? value : value + 'Z'));
const humanSize = (bytes: number) => bytes > 1024 * 1024 ? `${(bytes / 1024 / 1024).toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;
const statusText = { queued: '等待分析', running: '分析进行中', completed: '分析已完成', failed: '分析未完成' };
const kindNames = { numeric: '数值', categorical: '类别', datetime: '日期时间', boolean: '布尔' };

function clearAccountUrl() { const url = new URL(location.href); url.searchParams.delete('job'); url.searchParams.set('view', 'workspace'); url.searchParams.set('tab', 'overview'); history.replaceState(null, '', url); }

export default function App() {
  const [session, setSession] = useState<Session | null>(null); const [error, setError] = useState('');
  const load = useCallback(async () => { setError(''); try { setSession(await api<Session>('/session')); } catch (problem) { setError((problem as Error).message); } }, []);
  useEffect(() => { void load(); }, [load]);
  const accountId = session?.user?.id;
  const onAuthChange = useCallback((next: Session) => { setSession(current => { if (current?.user?.id !== accountId) return current; if (!next.authenticated || next.user?.id !== accountId) { clearAccountUrl(); if (accountId) localStorage.removeItem(`insight-selected-job:${accountId}`); } return next; }); }, [accountId]);
  const publicParams = new URLSearchParams(location.search);
  if (publicParams.has('example') || publicParams.get('view') === 'examples') return <PublicExamples slug={publicParams.get('example')}/>;
  if (!session) return <div className="boot-screen"><Brand/>{error ? <div className="boot-error"><CircleAlert aria-hidden="true" size={28}/><h2>暂时无法连接工作台</h2><p>{error}</p><button className="button primary" onClick={() => void load()}><RefreshCw aria-hidden="true" size={16}/>重新连接</button></div> : <Spinner label="正在连接数据研究室"/>}</div>;
  if (!session.authenticated || !session.user) return <AuthScreen brand={<Brand/>} illustration={<PaperStudy variant="login"/>} onLogin={next => { clearAccountUrl(); localStorage.removeItem('insight-selected-job'); if (next.user) localStorage.removeItem(`insight-selected-job:${next.user.id}`); setSession(next); }}/>;
  return <Workspace key={session.user.id} initialSession={session} onAuthChange={onAuthChange}/>;
}


function Brand({ compact = false }: { compact?: boolean }) {
  return <div className={`brand ${compact ? 'brand-compact' : ''}`}><span className="brand-rule" aria-hidden="true"/><div><strong>Insight Studio</strong><small>数据研究室</small></div></div>;
}

function Spinner({ label = '正在加载…' }: { label?: string }) { return <div className="loading-state"><LoaderCircle aria-hidden="true" className="spin" size={25} /><p>{label}</p></div>; }
function Status({ job }: { job: Job }) { return <span className={`status status-${job.status}`}><span className={job.status === 'running' || job.status === 'queued' ? 'pulse' : ''} />{statusText[job.status]}</span>; }
function Empty({ icon: IconComponent = FolderOpen, title, body }: { icon?: Icon; title: string; body: string }) { return <div className="empty"><div className="empty-symbol"><IconComponent aria-hidden="true" size={25} /></div><h3>{title}</h3><p>{body}</p></div>; }
function SectionHeading({ title, right }: { eyebrow?: string; title: string; right?: React.ReactNode }) { return <div className="section-heading"><h2>{title}</h2>{right}</div>; }
function PaperStudy({ variant = 'workspace' }: { variant?: 'workspace' | 'login' }) {
  return <figure className={`paper-study paper-study-${variant}`}><svg viewBox="0 0 560 270" fill="none" aria-hidden="true"><path d="M37 222H525" stroke="#D8D3C9"/><g transform="translate(64 45) rotate(-7 105 88)"><rect x="9" y="10" width="177" height="160" fill="#E7E2D8"/><rect x="0" y="0" width="177" height="160" fill="#F9F7F1" stroke="#C9C2B5"/><path d="M24 29H145M24 46H125M24 63H145M24 80H103M24 117H145M24 134H145" stroke="#CCC5B9"/><path d="M24 99H145" stroke="#8A8173"/></g><g transform="translate(220 30) rotate(5 105 88)"><rect x="8" y="10" width="179" height="166" fill="#E3DDD1"/><rect width="179" height="166" fill="#FFFDF8" stroke="#C9C2B5"/><path d="M25 137V34M25 137H154" stroke="#A49A8B"/>{[[44,118],[63,105],[81,114],[101,76],[124,88],[145,49]].map(([x,y]) => <circle key={x} cx={x} cy={y} r="3.5" fill="#8D9789"/>)}<path d="M43 116L64 105L81 111L101 79L124 86L145 53" stroke="#7E8A7A" strokeWidth="1.2"/></g><g transform="translate(369 85) rotate(-5 75 70)"><rect x="7" y="8" width="137" height="129" fill="#DFD7CA"/><rect width="137" height="129" fill="#F3F0E8" stroke="#C7BEAF"/><path d="M20 26H114M20 43H97M20 60H114M20 103H114" stroke="#C2B8A8"/><circle cx="105" cy="82" r="8" stroke="#7E5555" strokeWidth="1.5"/><path d="M99 82L103 86L112 76" stroke="#7E5555" strokeWidth="1.5"/></g></svg><figcaption><span>资料</span><span>观察</span><span>记录</span><small>分析流程示意</small></figcaption></figure>;
}


function UploadComposer({ session, usage, usageLoading, usageError, onUsage, onStarted, onError, onBusyChange, compact = false }: { session: Session; onStarted: (job: Job) => void; onError: (error: unknown) => void; compact?: boolean; onUsage: () => void; onBusyChange?: (busy: boolean) => void } & UsageState) {
  const formId = useId(); const operation = useRef(false);
  const input = useRef<HTMLInputElement>(null); const [upload, setUpload] = useState<Upload | null>(null); const [uploading, setUploading] = useState(false); const [starting, setStarting] = useState(false); const [dragging, setDragging] = useState(false); const [selected, setSelected] = useState(''); const [goal, setGoal] = useState(''); const [target, setTarget] = useState(''); const [llmChoice, setLlmChoice] = useState<boolean | null>(null); const [advanced, setAdvanced] = useState(false);
  const modelAvailable = session.model_enabled && !!usage && !usage.locked && !usageError && !usageLoading;
  const useLlm = modelAvailable && (llmChoice ?? true);
  const [schema,setSchema] = useState<UploadSchema | null>(null);
  const [schemaLoading,setSchemaLoading] = useState(false);
  const [schemaError,setSchemaError] = useState('');
  useEffect(() => {
    let cancelled = false;
    setSchema(null); setSchemaError(''); setTarget('');
    if (!upload || !selected) { setSchemaLoading(false); return; }
    setSchemaLoading(true);
    api<UploadSchema>(`/uploads/${encodeURIComponent(upload.upload_id)}/schema?selected_file=${encodeURIComponent(selected)}`)
      .then(value => { if (!cancelled) setSchema(value); })
      .catch(error => { if (!cancelled) setSchemaError((error as Error).message); })
      .finally(() => { if (!cancelled) setSchemaLoading(false); });
    return () => {cancelled = true;};
  }, [upload?.upload_id,selected]);
  async function receive(file?: File) {
    if (!file || operation.current) return;
    if (!/\.(csv|tsv|xlsx|zip)$/i.test(file.name)) { onError(new Error('请选择 CSV、TSV、XLSX 或 ZIP 格式的数据集。')); return; }
    if (file.size > session.limits.max_upload_mb * 1024 * 1024) { onError(new Error(`文件超过 ${session.limits.max_upload_mb} MB 上传限制。`)); return; }
    operation.current = true; onBusyChange?.(true); setUploading(true); const form = new FormData(); form.append('file', file);
    try { const uploaded = await api<Upload>('/uploads', { method: 'POST', body: form }); setUpload(uploaded); setSelected(uploaded.files[0]?.name || ''); }
    catch (error) { onError(error); } finally { operation.current = false; onBusyChange?.(false); setUploading(false); if (input.current) input.current.value = ''; }
  }
  function drop(event: DragEvent) { event.preventDefault(); setDragging(false); void receive(event.dataTransfer.files[0]); }
  async function start(event: FormEvent) {
    event.preventDefault(); if (!upload || !selected || operation.current) return; operation.current = true; onBusyChange?.(true); setStarting(true);
    try { const job = await api<Job>('/jobs', { method: 'POST', body: JSON.stringify({ upload_id: upload.upload_id, selected_file: selected, goal: goal.trim(), use_llm: useLlm && modelAvailable, ...(target.trim() ? { target_column: target.trim() } : {}) }) }); onStarted(job); }
    catch (error) { onError(error); } finally { operation.current = false; onBusyChange?.(false); setStarting(false); }
  }
  return <form className={`upload-composer ${compact ? 'compact' : ''}`} onSubmit={start} aria-busy={uploading || starting}><fieldset className="upload-fieldset" disabled={uploading || starting}><legend className="visually-hidden">数据集与分析设置</legend>
    <div className="card-heading"><span className="icon-box mint"><UploadCloud aria-hidden="true" size={19} /></span><div><h2>导入数据集</h2><p>选择本地文件，或上传 Kaggle 下载的数据集</p></div><span className="step-badge">数据源</span></div>
    <input ref={input} tabIndex={-1} type="file" accept=".csv,.tsv,.xlsx,.zip" onChange={event => void receive(event.target.files?.[0])} className="visually-hidden" aria-label="选择数据集文件" />
    {!upload ? <button type="button" className={`dropzone ${dragging ? 'dragging' : ''}`} onDragOver={event => { event.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={drop} onClick={() => input.current?.click()} disabled={uploading}><span className="upload-glyph">{uploading ? <LoaderCircle aria-hidden="true" size={28} className="spin" /> : <UploadCloud aria-hidden="true" size={28} strokeWidth={1.5} />}</span><strong>{uploading ? '正在安全上传数据集…' : '拖入数据文件，或点击选择'}</strong><span>CSV、TSV、XLSX、ZIP <i>·</i> 最大 {session.limits.max_upload_mb} MB</span><span className="choose-file">{uploading ? '上传中' : '选择本地文件'}{!uploading && <ArrowUpRight aria-hidden="true" size={14} />}</span></button> : <div className="uploaded-file"><span className="icon-box mint">{/\.zip$/i.test(upload.filename) ? <FileArchive aria-hidden="true" size={23} /> : <FileSpreadsheet aria-hidden="true" size={23} />}</span><div><strong title={upload.filename}>{upload.filename}</strong><p><CheckCheck aria-hidden="true" size={12} /> 上传成功 · {upload.files.length} 个可分析文件</p></div><button className="icon-button" type="button" title="重新选择文件" aria-label="重新选择文件" onClick={() => input.current?.click()} disabled={uploading || starting}>{uploading ? <LoaderCircle aria-hidden="true" className="spin" size={17} /> : <RefreshCw aria-hidden="true" size={17} />}</button></div>}
    {upload && <div className="upload-options"><label className="field-label" htmlFor={`${formId}-member`}>分析文件 <span>一次选择一张表</span></label><div className="select-wrap"><select id={`${formId}-member`} value={selected} onChange={event => setSelected(event.target.value)} disabled={starting}>{upload.files.map(file => <option key={file.name} value={file.name}>{file.name} · {humanSize(file.size)}</option>)}</select><ChevronDown aria-hidden="true" size={15} /></div>{!upload.files.length && <p className="error-text">文件中没有可分析的表格，请重新选择。</p>}</div>}
    {upload && <section className="question-setup" aria-label="选择你想了解的问题">
      {schemaLoading && <p role="status">正在识别字段，准备可直接选择的问题…</p>}
      {schemaError && <p role="alert" className="error-text">{schemaError}</p>}
      {schema && <><label className="field-label" htmlFor={`${formId}-focus`}>你想重点了解哪个指标？</label><select id={`${formId}-focus`} value={target} onChange={e=>setTarget(e.target.value)}><option value="">根据问题自动选择{schema.suggested_target ? `（默认${schema.columns.find(c=>c.name===schema.suggested_target)?.label}）` : ''}</option>{schema.columns.filter(c=>c.selectable).map(c=><option key={c.name} value={c.name}>{c.label}</option>)}</select>
        <p className="focus-meaning">{schema.columns.find(c=>c.name===(target||schema.suggested_target))?.meaning}</p>
        <div className="question-presets">{schema.questions.map(q=><button key={q.label} type="button" onClick={()=>{setGoal(q.goal);setTarget(q.target||'');}}>{q.label}<ArrowUpRight size={13} aria-hidden="true"/></button>)}</div></>}
    </section>}
    <div className="goal-field"><label className="field-label" htmlFor={`${formId}-goal`}>你想了解什么？<span>选填，也可以使用上方的问题</span></label><textarea id={`${formId}-goal`} name="goal" autoComplete="off" value={goal} onChange={event => setGoal(event.target.value)} maxLength={2000} placeholder="例如：不同预订渠道的取消比例有何差异？这些数据还不能说明什么？" rows={2} /></div>
    <ModelChoice usage={usage} usageLoading={usageLoading} usageError={usageError} modelEnabled={session.model_enabled} checked={useLlm} onChange={setLlmChoice} onUsage={onUsage} />
    <button className="text-button advanced-toggle" type="button" aria-expanded={advanced} onClick={() => setAdvanced(!advanced)}><SlidersHorizontal aria-hidden="true" size={14} />分析选项<ChevronDown aria-hidden="true" size={14} className={advanced ? 'rotate' : ''} /></button>
    {advanced && <div className="advanced-options"><label className="field-label" htmlFor={`${formId}-target`}>关注字段<span>选填，输入完整列名</span></label><input id={`${formId}-target`} name="target" autoComplete="off" value={target} onChange={event => setTarget(event.target.value)} placeholder="若需手动选择，请输入完整列名" maxLength={200} /></div>}
    <div className="upload-action"><p><ShieldCheck aria-hidden="true" size={14} /><span>原始数据保留在当前私有部署</span></p><button className="button primary" type="submit" disabled={!upload || !selected || uploading || starting || schemaLoading || !!schemaError}>{starting ? <LoaderCircle aria-hidden="true" size={17} className="spin" /> : <Sparkles aria-hidden="true" size={16} />}开始分析<ArrowRight aria-hidden="true" size={16} /></button></div>
  </fieldset></form>;
}

function Welcome({ session, usage, usageLoading, usageError, onUsage, onStarted, onError, onDemo, demoBusy, onGuide, jobs, onSelect, onHistory }: { session: Session; onStarted: (job: Job) => void; onError: (error: unknown) => void; onDemo: () => void; demoBusy: boolean; onGuide: () => void; onUsage: () => void; jobs: Job[]; onSelect: (id: string) => void; onHistory: () => void } & UsageState) {
  const recent = jobs.filter(item => item.status === 'completed' && !item.is_demo).sort((a,b) => b.created_at.localeCompare(a.created_at))[0];
  return <><div className="workspace-heading"><div><h1>数据研究室</h1><p>告诉我们你想了解什么，先看结论，再展开数字和图表。</p></div><span className="workspace-ready"><span/>{session.model_enabled && usage && !usage.locked && !usageError ? 'Agent 已就绪' : '统计引擎已就绪'}</span></div>
    <div className="welcome-grid"><section className="card upload-card"><UploadComposer session={session} usage={usage} usageLoading={usageLoading} usageError={usageError} onUsage={onUsage} onStarted={onStarted} onError={onError}/></section><aside className="welcome-aside"><section className="research-note"><PaperStudy/><div className="research-index"><h2>一份报告，读懂主要发现</h2><ul><li><span>发现了什么</span><small>先用日常语言回答问题</small></li><li><span>为什么这样理解</span><small>把数据含义说清楚</small></li><li><span>接下来了解什么</span><small>围绕发现提出具体问题</small></li><li><span>依据在哪里</span><small>展开数字、图表与适用范围</small></li></ul><p>明确区分观测到的关系、仍不确定的解释，以及需要补充的证据。</p></div></section><section className="demo-console"><div><h3>先看看一份分析</h3><p>{recent ? recent.filename : '从商业、金融、医疗、娱乐与教育的真实数据问题出发。'}</p></div><div className="example-actions"><a className="button secondary" href="?view=examples">公开分析示例<ArrowUpRight size={14} aria-hidden="true"/></a>{recent && <button className="button secondary" onClick={() => onSelect(recent.id)}>打开最近分析<ArrowUpRight size={14} aria-hidden="true"/></button>}<button className={recent ? 'text-button' : 'button secondary'} onClick={onDemo} disabled={demoBusy}>{demoBusy ? <LoaderCircle className="spin" size={15} aria-hidden="true"/> : <Play size={14} aria-hidden="true"/>}合成流程演示</button></div></section><button className="workspace-guide" onClick={onGuide}><BookOpen size={15} aria-hidden="true"/><span>格式、分析范围与使用说明</span><ChevronRight size={15} aria-hidden="true"/></button></aside></div>
    <section className="workspace-history"><SectionHeading title="分析档案" right={<button className="text-button" onClick={onHistory}>全部记录 <span>{jobs.length}</span><ChevronRight size={14} aria-hidden="true"/></button>}/>{jobs.length ? <div className="workspace-records">{jobs.slice(0,4).map(item => <button className="workspace-record" key={item.id} onClick={() => onSelect(item.id)}><span className="record-file"><FileSpreadsheet size={20} aria-hidden="true"/></span><span className="record-name"><strong>{item.filename}</strong><small>{item.is_demo ? '合成数据演示' : item.goal || '探索性数据分析'}</small></span><Status job={item}/><time>{date(item.created_at)}</time><ChevronRight size={16} aria-hidden="true"/></button>)}</div> : <div className="workspace-no-records"><History size={19} aria-hidden="true"/><p>还没有分析档案。可以导入资料，或先阅读公开分析示例。</p></div>}</section>
  </>;
}

function JobProgress({ job, onRetry, retryBusy }: { job: Job; onRetry: () => void; retryBusy: boolean }) {
  const failed = job.status === 'failed';
  return <div className="progress-layout"><div className="card progress-card"><span className={`progress-emblem ${failed ? 'failed' : ''}`}>{failed ? <CircleAlert aria-hidden="true" size={29} /> : <Workflow aria-hidden="true" size={29} />}</span><span className="progress-label">{failed ? '任务已中断' : 'Agent 正在分析'}</span><h2>{failed ? '分析任务未完成' : '分析任务正在执行'}</h2><p>{failed ? job.error || '数据集分析遇到了问题，请检查文件后重试。' : '你可以在这里查看每一步的进展。分析完成后，看板会自动呈现。'}</p><div className="progress-line" role="progressbar" aria-label="数据分析任务进度" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.min(100, Math.max(0, job.progress))} aria-valuetext={`${number(job.progress)}%，${job.steps.find(step => step.status === 'running')?.label || statusText[job.status]}`}><span style={{ width: `${Math.min(100, Math.max(0, job.progress))}%` }} /></div><div className="progress-caption"><span role="status" aria-live="polite" aria-atomic="true">{failed ? '分析中断' : job.steps.find(step => step.status === 'running')?.label || '正在准备分析环境'}</span><strong>{number(job.progress)}%</strong></div>{failed && <button className="button primary" onClick={onRetry} disabled={retryBusy}>{retryBusy ? <LoaderCircle aria-hidden="true" size={16} className="spin" /> : <RefreshCw aria-hidden="true" size={16} />}重新分析</button>}<div className="progress-file"><FileSpreadsheet aria-hidden="true" size={16} /><span>{job.filename}</span>{job.is_demo && <span className="tag">合成演示数据</span>}</div></div><div className="card steps-card"><div className="card-heading"><Workflow aria-hidden="true" size={20} /><div><h2>Agent 工作记录</h2><p>有条理地探索每一个问题</p></div></div><Steps job={job} /></div></div>;
}
function Steps({ job }: { job: Job }) { return <div className="steps">{job.steps.map((step, index) => <div className={`step step-${step.status}`} key={step.key}><span className="step-marker">{step.status === 'completed' ? <Check aria-hidden="true" size={14} /> : step.status === 'running' ? <LoaderCircle aria-hidden="true" className="spin" size={14} /> : step.status === 'failed' ? <X aria-hidden="true" size={14} /> : String(index + 1).padStart(2, '0')}</span><div><h3>{step.label}<span>{({ pending: '待开始', running: '进行中', completed: '已完成', failed: '未完成' })[step.status]}</span></h3>{step.detail && <p>{step.detail}</p>}</div></div>)}</div>; }

function Metric({ icon: IconComponent, label, value, suffix, footer, accent = '' }: { icon: Icon; label: string; value: string; suffix?: string; footer: string; accent?: string }) { return <div className={`metric-card ${accent}`}><div className="metric-top"><span>{label}</span><IconComponent aria-hidden="true" size={16} /></div><div className="metric-value">{value}{suffix && <small>{suffix}</small>}</div><p>{footer}</p></div>; }

function InsightCards({ result, limit }: { result: Result; limit?: number }) { const items = limit ? result.insights.slice(0, limit) : result.insights; return <div className="insight-list">{items.length ? items.map((item, index) => <article className={`insight-item insight-${item.level}`} key={`${item.title}-${index}`}><span className="insight-index">{String(index + 1).padStart(2, '0')}</span><div><h3>{item.title}</h3><p>{item.body}</p><div className="evidence"><Fingerprint aria-hidden="true" size={13} /><span>{item.evidence}</span></div></div></article>) : <p className="muted">当前数据未生成额外洞察，可查看图表与字段统计继续探索。</p>}</div>; }
function Quality({ result }: { result: Result }) {
  const {quality_score: score, duplicate_rows: duplicates} = result.overview;
  if (typeof score !== 'number' || typeof duplicates !== 'number' || !Number.isFinite(score) || !Number.isFinite(duplicates)) return <div className="card quality-card"><div className="card-title-row"><h3>数据范围说明</h3><ShieldCheck aria-hidden="true" size={17}/></div><p className="quality-note">此报告只保留选定分析字段，不对原始数据作质量评级。</p></div>;
  const quality = Math.max(0, Math.min(100, score));
  return <div className="card quality-card"><div className="card-title-row"><h3>数据质量速览</h3><ShieldCheck aria-hidden="true" size={17} /></div><div className="quality-main"><div className="quality-ring"><svg viewBox="0 0 110 110"><circle cx="55" cy="55" r="44" className="ring-track" /><circle cx="55" cy="55" r="44" className="ring-value" strokeDasharray={`${quality / 100 * 276.46} 276.46`} /></svg><div><strong>{number(quality)}</strong><span>/ 100</span></div></div><div className="quality-message"><strong>{quality >= 90 ? '数据基础良好' : quality >= 70 ? '仍有优化空间' : '建议先清理数据'}</strong><p>从完整性与重复情况，了解数据的起点。</p></div></div><div className="quality-details"><div><span>缺失单元格</span><strong>{number(result.overview.missing_cells)}<small>{number(result.overview.missing_pct)}%</small></strong></div><div><span>重复数据行</span><strong>{number(duplicates)}<small>行</small></strong></div><div><span>字段结构</span><strong>{result.overview.numeric_columns}<small>数值</small><b>/</b>{result.overview.categorical_columns}<small>类别</small></strong></div></div><p className="quality-note">启发式数据质量参考分，不代表模型准确率。</p></div>;
}
function Overview({ result, setTab }: { result: Result; setTab: (tab: Tab) => void }) {
  if (result.brief && result.brief.version >= 1) return <><Brief result={result} onExplore={()=>setTab('charts')}/><details className="brief-methods"><summary>查看数据质量、统计方法与完整分析记录</summary><EdaOverviewSummary result={result} onExplore={()=>setTab('charts')}/><Quality result={result}/><InsightCards result={result}/></details></>;
  return <><EdaOverviewSummary result={result} onExplore={() => setTab('charts')}/><div className="overview-grid"><section className="card summary-card"><div className="summary-kicker"><span>分析手记</span><span className="tag">{result.agent.mode === 'llm' ? '模型增强分析' : '统计分析'}</span></div><p className="summary-text">{result.summary}</p><div className="summary-footer"><span><CheckCheck aria-hidden="true" size={14}/>基于当前分析范围</span><span><Clock3 aria-hidden="true" size={13}/>{number(result.duration_seconds)} 秒完成</span></div></section><Quality result={result}/></div>
    <div className="research-layout"><section className="research-charts"><SectionHeading title="图表预览" right={<button className="text-button" onClick={() => setTab('charts')}>查看全部 {result.charts.length} 张<ChevronRight aria-hidden="true" size={14}/></button>}/>{result.charts.length ? <div className="research-chart-stack">{result.charts.slice(0,2).map(chart => <ChartCard key={chart.id} chart={chart}/>)}</div> : <div className="card"><Empty title="没有可绘制的字段组合" body="可在字段与数据中检查数据类型和完整性。" icon={BarChart3}/></div>}</section><aside className="evidence-sidebar"><SectionHeading title="数据洞察" right={<span className="insight-count">{result.insights.length} 条</span>}/><div className="card insights-card"><InsightCards result={result}/></div>{result.recommendations.length > 0 && <section className="recommendations"><div className="recommendations-heading"><ArrowUpRight aria-hidden="true" size={17}/><h3>下一步建议</h3></div><ol>{result.recommendations.map((item,index) => <li key={index}>{item}</li>)}</ol></section>}</aside></div>
  </>;
}


function Data({ result }: { result: Result }) {
  const [search, setSearch] = useState(''); const [view, setView] = useState<'columns' | 'preview'>('columns');
  const columns = result.columns.filter(column => column.name.toLocaleLowerCase().includes(search.toLocaleLowerCase()));
  function display(value: unknown) { if (value === null || value === undefined || value === '') return <span className="null-value">—</span>; if (typeof value === 'number') return number(value); return String(value); }
  return <><div className="tab-description"><div><h2>字段与数据</h2><p>{result.source.sheet ? `工作表：${result.source.sheet} · ` : ''}字段类型、完整性与统计量，帮助你理解数据结构。</p></div><span className="pill"><Table2 aria-hidden="true" size={14} />{number(result.overview.columns)} 个字段</span></div><div className="card data-card"><div className="data-toolbar"><div className="segmented"><button className={view === 'columns' ? 'active' : ''} onClick={() => setView('columns')}><Database aria-hidden="true" size={14} />字段统计</button><button className={view === 'preview' ? 'active' : ''} onClick={() => setView('preview')}><Table2 aria-hidden="true" size={14} />数据预览</button></div>{view === 'columns' && <label className="search-box"><Search aria-hidden="true" size={15} /><input placeholder="搜索字段名称" value={search} onChange={event => setSearch(event.target.value)} aria-label="搜索字段" />{search && <button className="icon-button" onClick={() => setSearch('')} aria-label="清除搜索"><X aria-hidden="true" size={14} /></button>}</label>}</div><div className="table-scroll">{view === 'columns' ? <table><thead><tr><th>字段名称</th><th>类型</th><th>缺失率</th><th>唯一值</th><th>平均值</th><th>中位数</th><th>最小值</th><th>最大值</th></tr></thead><tbody>{columns.map(column => <tr key={column.name}><td className="column-name" title={column.name}>{column.name}<small>{column.dtype}</small></td><td><span className={`type-tag type-${column.kind}`}>{kindNames[column.kind]}</span></td><td><div className="missing-cell"><span className="small-meter"><i style={{ width: `${Math.min(100, column.missing_pct)}%` }} /></span>{number(column.missing_pct)}%</div></td><td>{number(column.unique)}</td><td>{display(column.mean)}</td><td>{display(column.median)}</td><td title={String(column.min ?? '')}>{display(column.min)}</td><td title={String(column.max ?? '')}>{display(column.max)}</td></tr>)}</tbody></table> : <table className="preview-table"><thead><tr><th className="row-number">#</th>{result.preview.columns.map(column => <th key={column}>{column}</th>)}</tr></thead><tbody>{result.preview.rows.map((row, index) => <tr key={index}><td className="row-number">{index + 1}</td>{row.map((value, column) => <td key={column} title={value === null ? '空值' : String(value)}>{display(value)}</td>)}</tr>)}</tbody></table>}</div>{view === 'columns' && columns.length === 0 && <Empty title="没有找到匹配的字段" body="换一个关键词，或清除搜索后查看全部字段。" icon={Search} />}<div className="table-footer"><span>{view === 'columns' ? `展示 ${columns.length} / ${result.columns.length} 个字段` : `预览前 ${result.preview.rows.length} 行，完整分析使用 ${number(result.source.analyzed_rows)} 行`}</span><span>统计范围：{result.source.sampled ? '前 N 行截取数据' : '当前分析数据'}</span></div></div>{result.source.notes.length > 0 && <div className="source-notes"><CircleAlert aria-hidden="true" size={16} /><div><strong>数据读取说明</strong>{result.source.notes.map((note, index) => <p key={index}>{note}</p>)}</div></div>}</>;
}
function Agent({ job, result }: { job: Job; result: Result }) {
  return <><div className="tab-description"><div><h2>Agent 分析过程</h2><p>从数据读取到报告生成，查看 Agent 如何得出结论。</p></div><span className="pill"><Workflow aria-hidden="true" size={14} />{job.steps.filter(step => step.status === 'completed').length} 个步骤已完成</span></div><div className="agent-grid"><div className="card steps-card"><div className="card-title-row"><h3>分析过程</h3><span className="tag"><Check aria-hidden="true" size={11} />完成</span></div><Steps job={job} /></div><div className="agent-context"><div className="card agent-config"><span className="icon-box mint"><Sparkles aria-hidden="true" size={20} /></span><h3>这次分析如何运行</h3><dl><div><dt>分析模式</dt><dd>{result.agent.mode === 'llm' ? '统计分析 + 语言模型' : '统计分析'}</dd></div><div><dt>洞察模型</dt><dd>{result.agent.model || '统计规则引擎'}</dd></div><div><dt>分析用时</dt><dd>{number(result.duration_seconds)} 秒</dd></div><div><dt>分析问题</dt><dd>{job.goal || '先了解主要发现与解释范围'}</dd></div></dl></div><div className="card agent-notes"><div className="card-title-row"><h3>分析边界与说明</h3><ShieldCheck aria-hidden="true" size={17} /></div>{result.agent.notes.length ? result.agent.notes.map((note, index) => <p key={index}><Check aria-hidden="true" size={14} /><span>{note}</span></p>) : <p><Check aria-hidden="true" size={14} /><span>洞察以汇总统计为依据，建议结合业务背景进一步验证。</span></p>}<p><Fingerprint aria-hidden="true" size={14} /><span>相关性用于探索变量关系，不代表因果关系。</span></p></div></div></div>{result.agent.narrative && <div className="card narrative-card"><h3>进一步的分析解读</h3><div className="plain-narrative">{result.agent.narrative}</div></div>}<SectionHeading title="洞察与统计依据" /><div className="card insights-card"><InsightCards result={result} /></div></>;
}
function Dashboard({ job, tab, setTab, onUpgrade }: { job: Job; tab: Tab; setTab: (tab: Tab) => void; onUpgrade: () => void }) {
  const result = job.result!; const overview = result.overview;
  const tabs: { id: Tab; label: string; icon: Icon; count?: number }[] = [{ id: 'overview', label: '结论与解释', icon: LayoutDashboard }, { id: 'charts', label: '统计依据', icon: BarChart3, count: result.charts.length }, { id: 'data', label: '字段与数据', icon: Table2 }, { id: 'agent', label: 'Agent 过程', icon: Workflow }];
  return <>{!result.brief?.question_answers && tab === 'overview' && <div className="legacy-eda-notice compact"><CircleAlert aria-hidden="true" size={16}/><div><strong>新版结论解析可用</strong><p>这份旧报告仍可正常浏览。重新分析可获得问题回答、日常语言解释与证据边界；默认免费统计升级，模型调用需再次明确选择。</p></div><button className="button secondary" onClick={onUpgrade}><RefreshCw aria-hidden="true" size={14}/>使用新版分析</button></div>}<div className={`metrics-grid ${result.brief ? 'concise-metrics' : ''}`}><Metric icon={Database} label="分析数据行" value={number(overview.rows)} footer={result.source.sampled ? result.source.total_rows ? `截取自 ${number(result.source.total_rows)} 行的前段` : `前 ${number(result.source.analyzed_rows)} 行，总量未知` : '已读取的有效记录'} /><Metric icon={Table2} label="数据字段" value={number(overview.columns)} footer={`${overview.numeric_columns} 个数值 · ${overview.categorical_columns} 个类别`} /><Metric icon={BarChart3} label={result.brief ? "已比较目标关系" : "可视化图表"} value={number(result.brief?.coverage.relationships_evaluated ?? result.charts.length)} footer={result.brief ? "跨全部可用数值字段" : "探索分布、关系与趋势"} /><Metric icon={Sparkles} label="主要发现" value={number(result.brief?.findings.length ?? result.insights.length)} footer="每条发现附有统计依据" accent="metric-highlight" /></div>
    {job.use_llm === true && result.agent.mode !== 'llm' && <div className="legacy-eda-notice compact"><CircleAlert aria-hidden="true" size={16}/><div><strong>本次模型解释未采用，当前为统计报告。</strong><p>图表与统计已保留；调用结果及费用说明见 Agent 过程。</p></div>{tab !== 'agent' && <button className="button secondary" onClick={() => { setTab('agent'); document.getElementById('tab-agent')?.focus(); }}><Workflow aria-hidden="true" size={14}/>查看 Agent 过程</button>}</div>}
    {result.source.sampled && <div className="notice"><CircleAlert aria-hidden="true" size={16} /><span>本次分析使用 {number(result.source.analyzed_rows)} 行前段截取数据（共 {result.source.total_rows ? number(result.source.total_rows) : '未知'} 行），以下统计与洞察均基于该截取范围。</span></div>}
    <div className="result-tabs" role="tablist" aria-label="分析结果"><div>{tabs.map(item => <button key={item.id} role="tab" tabIndex={tab === item.id ? 0 : -1} onKeyDown={event => { const current = tabs.findIndex(candidate => candidate.id === tab); const next = event.key === 'ArrowRight' ? (current + 1) % tabs.length : event.key === 'ArrowLeft' ? (current + tabs.length - 1) % tabs.length : event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : -1; if (next >= 0) { event.preventDefault(); setTab(tabs[next].id); document.getElementById(`tab-${tabs[next].id}`)?.focus(); } }} aria-selected={tab === item.id} aria-controls={`panel-${item.id}`} id={`tab-${item.id}`} className={tab === item.id ? 'active' : ''} onClick={() => setTab(item.id)}><item.icon aria-hidden="true" size={16} />{item.label}{item.count !== undefined && <span>{item.count}</span>}</button>)}</div><span className="result-tabs-note"><CheckCheck aria-hidden="true" size={13} />分析已就绪</span></div>
    <div role="tabpanel" tabIndex={0} id={`panel-${tab}`} aria-labelledby={`tab-${tab}`} className="tab-panel">{tab === 'overview' && <Overview result={result} setTab={setTab} />}{tab === 'charts' && <Exploration key={job.id} result={result} onUpgrade={onUpgrade}/>}{tab === 'data' && <Data result={result} />}{tab === 'agent' && <Agent job={job} result={result} />}</div>
  </>;
}
function HistoryPage({ jobs, loading, onSelect, onRefresh, onDelete, onNew, busyId }: { jobs: Job[]; loading: boolean; onSelect: (id: string) => void; onRefresh: () => void; onDelete: (job: Job) => void; onNew: () => void; busyId: string | null }) {
  const [search, setSearch] = useState(''); const [filter, setFilter] = useState('all'); const filtered = jobs.filter(job => (!search || job.filename.toLocaleLowerCase().includes(search.toLocaleLowerCase())) && (filter === 'all' || job.status === filter));
  return <><div className="page-heading"><div><h1>分析记录</h1><p>在这里找回数据集、分析过程与生成的报告。</p></div><button className="button primary" onClick={onNew}><Plus aria-hidden="true" size={16} />新建分析</button></div><div className="history-summary"><span><Files aria-hidden="true" size={18} /><strong>{jobs.length}</strong>份分析记录</span><span><CheckCheck aria-hidden="true" size={17} /><strong>{jobs.filter(job => job.status === 'completed').length}</strong>份已完成</span><button className="text-button" onClick={onRefresh} disabled={loading}><RefreshCw aria-hidden="true" size={14} className={loading ? 'spin' : ''} />刷新记录</button></div><div className="card history-card"><div className="data-toolbar"><div className="segmented"><button className={filter === 'all' ? 'active' : ''} onClick={() => setFilter('all')}>全部</button><button className={filter === 'completed' ? 'active' : ''} onClick={() => setFilter('completed')}>已完成</button><button className={filter === 'running' ? 'active' : ''} onClick={() => setFilter('running')}>进行中</button><button className={filter === 'failed' ? 'active' : ''} onClick={() => setFilter('failed')}>未完成</button></div><label className="search-box"><Search aria-hidden="true" size={15} /><input placeholder="搜索数据集" value={search} onChange={event => setSearch(event.target.value)} aria-label="搜索分析记录" /></label></div>{loading && !jobs.length ? <Spinner label="正在读取分析记录" /> : filtered.length ? <div className="history-list">{filtered.map(job => <article className="history-item" key={job.id}><span className={`history-file-icon ${job.is_demo ? 'demo' : ''}`}>{job.is_demo ? <FlaskConical aria-hidden="true" size={22} /> : <FileSpreadsheet aria-hidden="true" size={22} />}</span><button className="history-main" onClick={() => onSelect(job.id)} disabled={busyId === job.id}><strong>{job.filename}{job.is_demo && <span className="tag">合成演示</span>}</strong><span>{date(job.created_at)}<i>·</i>{job.goal || '开放式探索分析'}</span></button><Status job={job} /><button className="icon-button history-open" onClick={() => onSelect(job.id)} disabled={busyId === job.id} aria-label={`查看 ${job.filename}`} title="打开分析">{busyId === job.id ? <LoaderCircle aria-hidden="true" className="spin" size={18} /> : <ArrowUpRight aria-hidden="true" size={18} />}</button><button className="icon-button delete-button" onClick={() => onDelete(job)} disabled={job.status === 'running' || job.status === 'queued' || busyId === job.id} aria-label={`删除 ${job.filename} 的分析`} title={job.status === 'running' || job.status === 'queued' ? '进行中的分析不能删除' : '删除分析记录'}><Trash2 aria-hidden="true" size={16} /></button></article>)}</div> : <Empty title={jobs.length ? '没有匹配的分析记录' : '你的第一条洞察，正等待被发现'} body={jobs.length ? '换一个关键词或筛选条件试试。' : '上传一份数据集，或运行合成数据演示，即可开始。'} icon={History} />}</div></>;
}
function Guide({ session, onNew, onDemo }: { session: Session; onNew: () => void; onDemo: () => void }) {
  return <><div className="page-heading"><div><h1>使用指南</h1><p>准备好一个问题，剩下的探索交给工作台。</p></div><button className="button primary" onClick={onNew}>开始新分析<ArrowRight aria-hidden="true" size={16} /></button></div><div className="guide-grid"><article className="card guide-card"><span className="guide-number">01</span><h2>准备一份表格数据</h2><p>从 Kaggle 数据集页面下载文件后上传，或直接选择本地数据。支持 CSV、TSV、XLSX，以及包含表格的 ZIP 压缩包。</p><div className="format-chips">{['.CSV', '.TSV', '.XLSX', '.ZIP'].map(text => <span key={text}><FileSpreadsheet aria-hidden="true" size={15} />{text}</span>)}</div><div className="guide-callout">单文件最大 {session.limits.max_upload_mb} MB。最多分析前 {number(session.limits.max_rows)} 行；超过 {session.limits.max_columns} 列的文件会被拒绝。大文件会明确说明截取范围。</div></article><article className="card guide-card"><span className="guide-number">02</span><h2>给分析一个方向</h2><p>上传完成后，选择要分析的文件。先写下你想回答的问题，再确认关注指标。系统会说明指标含义，逐项回答提到的关系，保留弱关系与证据不足的结果。</p><div className="guide-example"><span>试着这样提问</span><p>“不同预订渠道的取消比例有何差异？提前预订多久与取消记录有什么关系？这些差异不能说明什么？”</p></div><p className="guide-small">ZIP 中一次选择一个表格；XLSX 默认读取首个工作表。当前版本不自动关联多张表。</p></article><article className="card guide-card"><span className="guide-number">03</span><h2>跟随 Agent 的分析步骤</h2><p>工作台会读取字段、检查质量、计算统计量，探索分布与关系，再整理洞察和报告。你可以在运行时查看步骤进度。</p><div className="guide-pipeline"><span>数据读取</span><ChevronRight aria-hidden="true" size={13} /><span>统计与可视化</span><ChevronRight aria-hidden="true" size={13} /><span>洞察与报告</span></div><p className="guide-small">模型配置且预算可用时，AI Agent 默认启用，可在上传区取消勾选。普通新账号有 $1 USD 模型额度，管理员不限额但持续记录费用；额度用完或模型不可用时，统计分析、图表与规则洞察仍可使用。</p></article><article className="card guide-card"><span className="guide-number">04</span><h2>探索看板，带走报告</h2><p>先在结论与解释中逐项阅读问题答案，了解怎样理解、解释边界和下一步验证。需要核对数字时，再展开统计依据；字段与数据页保留字段统计和预览。</p><div className="format-chips"><span><FileCode2 aria-hidden="true" size={15} />Markdown 报告</span><span><FileCheck2 aria-hidden="true" size={15} />HTML 报告</span></div><p className="guide-small">专题探索支持字段搜索、类型筛选、图表分页、悬停、缩放与图片下载。分析记录中可重新打开结果或删除已完成、已失败的任务。</p></article></div><div className="card guide-boundaries"><span className="icon-box peach"><Lightbulb aria-hidden="true" size={20} /></span><div><h3>让结论与证据保持一致。</h3><p>观测到的差异不直接代表因果；历史比例不能替代个人风险判断；作品目录不等于观看量；自评量表也不能替代实际就业结果。所有结论只适用于本次读取的记录，仍需结合来源、指标定义和业务背景判断。</p></div><button className="button secondary" onClick={onDemo}><FlaskConical aria-hidden="true" size={15} />体验合成数据演示</button></div></>;
}

function Workspace({ initialSession, onAuthChange }: { initialSession: Session; onAuthChange: (session: Session) => void }) {
  const [session, setSession] = useState<Session | null>(initialSession); const [sessionError, setSessionError] = useState(''); const [page, setPage] = useState<Page>(() => { const value = new URLSearchParams(location.search).get('view'); return ['workspace','history','usage','guide'].includes(value || '') ? value as Page : 'workspace'; }); const [job, setJob] = useState<Job | null>(null); const [jobs, setJobs] = useState<Job[]>([]); const [jobsLoading, setJobsLoading] = useState(false); const [tab, setTab] = useState<Tab>(() => { const value = new URLSearchParams(location.search).get('tab'); return ['overview','charts','data','agent'].includes(value || '') ? value as Tab : 'overview'; }); const [uploadModal, setUploadModal] = useState(false); const [sidebar, setSidebar] = useState(false); const [busyId, setBusyId] = useState<string | null>(null); const [demoBusy, setDemoBusy] = useState(false); const [toast, setToast] = useState<{ message: string; error: boolean } | null>(null); const [pollError, setPollError] = useState(''); const recovered = useRef(false); const toastTimer = useRef<ReturnType<typeof setTimeout>>();
  const uploadBusyRef = useRef(false); const [uploadBusy, setUploadBusy] = useState(false); const uploadDialog = useRef<HTMLElement>(null); const sidebarDialog = useRef<HTMLElement>(null);
  const [usage, setUsage] = useState<Usage | null>(null); const [usageLoading, setUsageLoading] = useState(false); const [usageError, setUsageError] = useState(''); const [authorizeModal, setAuthorizeModal] = useState(false); const [upgradeJob, setUpgradeJob] = useState<Job | null>(null);
  const authorized = session?.authenticated && !!session.user;
  const isAdmin = session?.user?.role === 'admin';
  const selectionKey = `insight-selected-job:${session?.user?.id || 'unknown'}`;
  const mounted = useRef(true); useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  const [logoutBusy, setLogoutBusy] = useState(false); const logoutOperation = useRef(false);
  const notify = useCallback((message: string, error = false) => { setToast({ message, error }); clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(null), error ? 8000 : 4000); }, []);
  const handleError = useCallback((error: unknown) => { if (!mounted.current) return; if (error instanceof ApiError && error.status === 401) { onAuthChange({ ...initialSession, authenticated: false, user: null }); return; } notify(error instanceof Error ? error.message : 'Request failed.', true); }, [notify, onAuthChange, initialSession]);
  const loadSession = useCallback(async () => { setSessionError(''); try { const current = await api<Session>('/session'); setSession(current); if (!current.authenticated || current.user?.id !== initialSession.user?.id) onAuthChange(current); } catch (error) { setSessionError((error as Error).message); } }, [initialSession, onAuthChange]);
  useEffect(() => { void loadSession(); return () => clearTimeout(toastTimer.current); }, [loadSession]);
  const loadUsage = useCallback(async () => { setUsageLoading(true); try { const next = await api<Usage>('/usage'); setUsage(next); setUsageError(''); } catch (error) { setUsageError(error instanceof Error ? error.message : '用量读取失败'); if (error instanceof ApiError && error.status === 401) handleError(error); } finally { setUsageLoading(false); } }, [handleError]);
  const loadJobs = useCallback(async () => { setJobsLoading(true); try { const data = await api<{ jobs: Job[] }>('/jobs'); setJobs(data.jobs); } catch (error) { handleError(error); } finally { setJobsLoading(false); } }, [handleError]);
  const selectJob = useCallback(async (id: string, restore = false) => { setBusyId(id); try { const next = await api<Job>(`/jobs/${encodeURIComponent(id)}`); if (!mounted.current) return; setJob(next); if (!restore) { setTab('overview'); setPage('workspace'); } setSidebar(false); localStorage.setItem(selectionKey, id); setPollError(''); scrollTop(); } catch (error) { handleError(error); } finally { setBusyId(null); } }, [handleError, selectionKey]);
  useEffect(() => { if (!authorized || recovered.current) return; recovered.current = true; void loadJobs(); void loadUsage(); const saved = new URLSearchParams(location.search).get('job') || localStorage.getItem(selectionKey); if (saved && page === 'workspace') void selectJob(saved, true); }, [authorized, loadJobs, loadUsage, selectJob]);
  useEffect(() => {
    if (!job || !authorized || !['running', 'queued'].includes(job.status)) return;
    let disposed = false; let timer: ReturnType<typeof setTimeout>; let usagePolls = 0;
    const poll = async () => { try { const next = await api<Job>(`/jobs/${encodeURIComponent(job.id)}`); if (disposed) return; setJob(next); setPollError(''); if (++usagePolls % 3 === 0) void loadUsage(); if (next.status === 'completed' || next.status === 'failed') { void loadJobs(); void loadUsage(); if (next.status === 'completed') notify('分析已完成，你的数据看板已就绪。'); return; } } catch (error) { if (disposed) return; if (error instanceof ApiError && error.status === 401) { handleError(error); return; } setPollError((error as Error).message); } if (!disposed) timer = setTimeout(poll, 1500); };
    timer = setTimeout(poll, 1000); return () => { disposed = true; clearTimeout(timer); };
  }, [job?.id, job?.status, authorized, loadJobs, loadUsage, notify, handleError]);
  const handleUploadBusy = useCallback((busy: boolean) => { uploadBusyRef.current = busy; setUploadBusy(busy); }, []);
  const closeUpload = useCallback(() => { if (!uploadBusyRef.current) setUploadModal(false); }, []);
  useDialogFocus(uploadModal, uploadDialog, closeUpload, !uploadBusy);
  const closeSidebar = useCallback(() => setSidebar(false), []);
  useDialogFocus(sidebar, sidebarDialog, closeSidebar);
  useEffect(() => { if (!authorized || !recovered.current) return; const url = new URL(location.href); url.searchParams.set('view', page); if (job) url.searchParams.set('job', job.id); else url.searchParams.delete('job'); url.searchParams.set('tab', tab); history.replaceState(null, '', url); }, [page, job?.id, tab, authorized]);

  function navigate(next: Page) { setPage(next); setSidebar(false); scrollTop(); if (next === 'history') void loadJobs(); if (next === 'usage') void loadUsage(); }
  function started(next: Job) { if (!mounted.current) return; setJob(next); setPage('workspace'); setTab('overview'); setUploadModal(false); setSidebar(false); setPollError(''); localStorage.setItem(selectionKey, next.id); void loadJobs(); void loadUsage(); scrollTop(); }
  async function demo() { setDemoBusy(true); try { started(await api<Job>('/demo', { method: 'POST' })); } catch (error) { handleError(error); } finally { setDemoBusy(false); } }
  function retry() { if (job) { setUpgradeJob(job); void loadUsage(); } }
  async function deleteJob(target: Job) { if (!window.confirm(`删除“${target.filename}”的分析记录及报告？此操作无法撤销。`)) return; setBusyId(target.id); try { await api(`/jobs/${encodeURIComponent(target.id)}`, { method: 'DELETE' }); if (job?.id === target.id) { setJob(null); localStorage.removeItem(selectionKey); } await loadJobs(); notify('分析记录已删除。'); } catch (error) { handleError(error); } finally { setBusyId(null); } }
  async function logout() { if (logoutOperation.current) return; logoutOperation.current = true; setLogoutBusy(true); try { await api('/logout', { method: 'POST' }); localStorage.removeItem(selectionKey); localStorage.removeItem('insight-selected-job'); clearAccountUrl(); onAuthChange({ ...initialSession, authenticated: false, user: null }); } catch (error) { handleError(error); } finally { logoutOperation.current = false; setLogoutBusy(false); } }
  const openNew = () => { setUploadModal(true); setSidebar(false); void loadUsage(); };
  const openUsage = () => { if (uploadBusyRef.current) return; setUploadModal(false); navigate('usage'); };
  const closeAuthorize = useCallback(() => setAuthorizeModal(false), []);
  const closeUpgrade = useCallback(() => setUpgradeJob(null), []);
  const openUpgrade = () => { if (job) { setUpgradeJob(job); void loadUsage(); } };
  function modelAuthorized(next: Usage) { setUsage(next); setUsageError(''); setAuthorizeModal(false); void loadSession(); notify('模型密钥已验证并保存，各账号额度与历史用量继续保留。'); }
  if (!session) return <div className="boot-screen"><Brand />{sessionError ? <div className="boot-error"><CircleAlert aria-hidden="true" size={28} /><h2>暂时无法连接工作台</h2><p>{sessionError}</p><button className="button primary" onClick={() => void loadSession()}><RefreshCw aria-hidden="true" size={16} />重新连接</button></div> : <Spinner label="正在连接你的数据工作台" />}</div>;
  if (!authorized) return <Spinner/>;
  return <div className="app-shell"><a className="skip-link" href="#main-content">跳到主要内容</a>
    {sidebar && <button className="sidebar-backdrop" aria-label="关闭导航菜单" onClick={() => setSidebar(false)} />}
    <aside ref={sidebarDialog} tabIndex={-1} role={sidebar ? 'dialog' : undefined} aria-modal={sidebar || undefined} aria-label="导航菜单" className={`sidebar ${sidebar ? 'is-open' : ''}`} {...(uploadModal || authorizeModal || !!upgradeJob ? { inert: '' } : {})}><Brand /><button className="new-analysis" onClick={openNew}><Plus aria-hidden="true" size={17} />新建分析</button><div className="nav-label">目录</div><a className="public-example-entry" href="?view=examples"><BookOpen size={16} aria-hidden="true"/>公开分析示例<ArrowUpRight size={14} aria-hidden="true"/></a><nav>{[{ id: 'workspace' as Page, icon: LayoutDashboard, label: '研究室' }, { id: 'history' as Page, icon: History, label: '分析档案' }, { id: 'usage' as Page, icon: Coins, label: '模型用量' }, { id: 'guide' as Page, icon: BookOpen, label: '使用指南' }].map(item => <a key={item.id} href={`?view=${item.id}`} aria-current={page === item.id ? 'page' : undefined} className={page === item.id ? 'active' : ''} onClick={event => { if (!event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey) { event.preventDefault(); navigate(item.id); } }}><item.icon aria-hidden="true" size={18} /><span>{item.label}</span>{item.id === 'history' ? <small>{jobs.length}</small> : page === item.id && <ChevronRight aria-hidden="true" size={14} />}</a>)}</nav><div className="sidebar-recent"><div className="nav-label">最近的探索</div>{jobs.slice(0, 3).map(item => <button key={item.id} onClick={() => void selectJob(item.id)} className={job?.id === item.id && page === 'workspace' ? 'selected' : ''} title={item.filename}><span className={`recent-dot ${item.status}`} /><span>{item.filename}</span>{busyId === item.id && <LoaderCircle aria-hidden="true" size={12} className="spin" />}</button>)}{!jobs.length && <p>你的分析旅程，从这里开始。</p>}</div><div className="sidebar-bottom"><div className="private-note"><ShieldCheck aria-hidden="true" size={18} /><div><strong>你的私有数据空间</strong><span>自主部署 · 数据由你掌握</span></div></div><div className="sidebar-profile"><span className="avatar">{session.user!.username.slice(0,1).toUpperCase()}</span><div><strong title={session.user!.username}>{session.user!.username}</strong><span>{isAdmin ? '管理员' : '普通用户'}</span></div>{session.auth_required ? <button className="icon-button" onClick={() => void logout()} disabled={logoutBusy} aria-label="退出登录" title="退出登录"><LogOut aria-hidden="true" size={16} /></button> : <LockKeyhole aria-hidden="true" size={14} />}</div></div></aside>
    <div className="main-shell" {...(sidebar || uploadModal || authorizeModal || !!upgradeJob ? { inert: '' } : {})}><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" onClick={() => setSidebar(true)} aria-label="打开导航菜单"><Menu aria-hidden="true" size={21} /></button><span className="account-breadcrumb" title={session.user!.username}>{session.user!.username}的空间</span><ChevronRight aria-hidden="true" size={13} /><strong>{page === 'workspace' ? '数据工作台' : page === 'history' ? '分析记录' : page === 'usage' ? '模型用量' : '使用指南'}</strong></div><div className="topbar-right"><span className="connection"><span />服务已连接</span><button className={`model-pill usage-top-button ${usage?.locked ? 'usage-top-locked' : ''}`} onClick={openUsage} aria-label="查看模型用量与预算" title="查看模型用量与预算"><Coins aria-hidden="true" size={13} /><span>{usageError ? '用量暂不可用' : usage ? usageSummary(usage) : '读取模型预算'}</span></button><button className="icon-button topbar-help" onClick={() => navigate('guide')} aria-label="查看使用指南" title="使用指南"><BookOpen aria-hidden="true" size={17} /></button></div></header>
    <main id="main-content" className="main-content" tabIndex={-1}>{usage?.locked && page !== 'usage' && <div className="budget-top-alert"><LockKeyhole aria-hidden="true" size={14} /><span>{usage.unlimited === false && usage.remaining_usd !== null && usage.remaining_usd <= 0 ? '本账号模型额度已用完，可继续统计分析。' : '模型暂不可用，统计分析仍可使用。'}</span><button className="text-button" onClick={isAdmin ? () => setAuthorizeModal(true) : openUsage}>{isAdmin ? '管理模型密钥' : '查看用量'}<ArrowRight aria-hidden="true" size={12} /></button></div>}{page === 'workspace' ? !job ? <Welcome jobs={jobs} onSelect={id => void selectJob(id)} onHistory={() => navigate('history')} session={session} usage={usage} usageLoading={usageLoading} usageError={usageError} onUsage={openUsage} onStarted={started} onError={handleError} onDemo={() => void demo()} demoBusy={demoBusy} onGuide={() => navigate('guide')} /> : <><div className="analysis-heading"><div className="analysis-title"><button className="back-link" onClick={() => { setJob(null); localStorage.removeItem(selectionKey); }}><ArrowLeft aria-hidden="true" size={13} />返回工作台</button><div className="analysis-eyebrow">{job.is_demo && <span className="demo-label"><FlaskConical aria-hidden="true" size={11} />合成数据演示</span>}</div><h1>{job.result?.title || job.filename.replace(/\.[^.]+$/, '')}</h1><div className="analysis-meta"><span><FileSpreadsheet aria-hidden="true" size={13} />{job.filename}</span><i>·</i><span>{date(job.created_at)}</span><Status job={job} /></div></div><div className="report-actions">{job.status === 'completed' && job.result && <><a className="button secondary" href={`/api/jobs/${encodeURIComponent(job.id)}/report.md`} download><ArrowDownToLine aria-hidden="true" size={15} />Markdown</a><a className="button primary" href={`/api/jobs/${encodeURIComponent(job.id)}/report.html`} download><ArrowDownToLine aria-hidden="true" size={15} />导出报告 <span>HTML</span></a></>}<button className="icon-button heading-more" onClick={openNew} aria-label="新建分析" title="新建分析"><Plus aria-hidden="true" size={20} /></button></div></div>{pollError && <div className="notice warning"><CircleAlert aria-hidden="true" size={16} /><span>{pollError} 正在自动尝试重新连接，分析会继续在服务端运行。</span></div>}{job.status === 'completed' && job.result ? <Dashboard job={job} tab={tab} setTab={setTab} onUpgrade={openUpgrade}/> : job.status === 'completed' ? <div className="card"><Empty title="分析报告暂时不可用" body="请重新读取任务，或从分析记录中打开。" icon={CircleAlert} /><button className="button secondary centered" onClick={() => void selectJob(job.id)}><RefreshCw aria-hidden="true" size={16} />重新读取结果</button></div> : <JobProgress job={job} onRetry={() => void retry()} retryBusy={false} />}</> : page === 'history' ? <HistoryPage jobs={jobs} loading={jobsLoading} onSelect={id => void selectJob(id)} onRefresh={() => void loadJobs()} onDelete={target => void deleteJob(target)} onNew={openNew} busyId={busyId} /> : page === 'usage' ? <UsagePage isAdmin={isAdmin} usage={usage} usageLoading={usageLoading} usageError={usageError} onRefresh={() => void loadUsage()} onAuthorize={() => setAuthorizeModal(true)} onAnalyze={() => navigate('workspace')} /> : <Guide session={session} onNew={openNew} onDemo={() => void demo()} />}
    <footer className="footer"><span>Insight Studio <i>数据研究室</i></span><span className="footer-links"><a href="https://github.com/lingxiao001/insight-studio/blob/main/LICENSE" target="_blank" rel="noreferrer">AGPL-3.0</a><a href="https://github.com/lingxiao001/insight-studio" target="_blank" rel="noreferrer">Source</a></span><span><ShieldCheck aria-hidden="true" size={12}/>私有部署 · 服务端分析</span></footer></main></div>
    {uploadModal && <div className="modal-backdrop" onClick={event => { if (event.target === event.currentTarget) closeUpload(); }}><section ref={uploadDialog} className="modal" role="dialog" aria-modal="true" aria-label="新建数据分析" tabIndex={-1}><button className="icon-button modal-close" onClick={closeUpload} disabled={uploadBusy} aria-label="关闭新建分析窗口"><X aria-hidden="true" size={20} /></button><UploadComposer session={session} usage={usage} usageLoading={usageLoading} usageError={usageError} onUsage={openUsage} onStarted={started} onError={handleError} onBusyChange={handleUploadBusy} compact /></section></div>}
    {upgradeJob && <UpgradeAnalysisDialog job={upgradeJob} session={session} usage={usage} usageLoading={usageLoading} usageError={usageError} onClose={closeUpgrade} onStarted={next => { setUpgradeJob(null); started(next); }} onError={handleError} onUsage={() => { setUpgradeJob(null); openUsage(); }}/>}
    {authorizeModal && isAdmin && <AuthorizeModal usage={usage} onClose={closeAuthorize} onAuthorized={modelAuthorized} onError={handleError} />}
    {toast && <div className={`toast ${toast.error ? 'toast-error' : ''}`} role={toast.error ? 'alert' : 'status'}>{toast.error ? <CircleAlert aria-hidden="true" size={18} /> : <CheckCheck aria-hidden="true" size={18} />}<span>{toast.message}</span><button className="icon-button" onClick={() => setToast(null)} aria-label="关闭提示"><X aria-hidden="true" size={15} /></button></div>}
  </div>;
}
